package io.github.jesterportfolio.hearth.economy;

import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.inventory.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.sql.*;
import static io.github.jesterportfolio.hearth.economy.EconomyContent.*;
import static io.github.jesterportfolio.hearth.economy.EconomyEngine.*;

/** 기존 제한 DB worker를 재사용하되 SQL과 식별 발급자는 경제 전용으로 분리합니다. */
public final class EconomyStore implements InventoryStore {
    public enum Probe { NONE,ROLLBACK,COMMIT_UNKNOWN }
    public record Account(long balance,Stored inventory){}
    public record Offer(Key key,Market market,long balance){}
    public record Request(ServerProgressAccess.Context context,UUID id,Key key,int quantity,boolean buy,long marketRevision){public Request{Objects.requireNonNull(context);Objects.requireNonNull(id);Objects.requireNonNull(key);if(quantity<1||quantity>4096||marketRevision<0)throw new IllegalArgumentException("ECON_REQUEST");}String fingerprint(){return key+"/"+quantity+"/"+buy+"/"+marketRevision;}}
    public record Receipt(UUID id,long total,Account account,boolean replay){}
    public record Entry(UUID id,Key key,int quantity,boolean buy,long total,long inventoryRevision){}
    public record Inspection(Optional<Entry> entry,Account account){}

    private final PostgresProgressStore db;private final EconomyContent content;private final String contentHash;private final ServerProgressAccess issuer=new ServerProgressAccess();private volatile boolean ready;
    public EconomyStore(PostgresProgressStore db,EconomyContent content){this.db=db;this.content=content;this.contentHash=content.fingerprint();}
    public EconomyContent content(){return content;}
    public ServerProgressAccess.Context context(UUID realm,UUID player){return issuer.forVerifiedServerLink(realm,player);}
    private void access(ServerProgressAccess.Context ctx){issuer.requireIssued(ctx);if(!ready)throw new StorageFailure("economy","SCHEMA_NOT_READY");}
    void validate(ServerProgressAccess.Context context){access(context);}
    private static StorageFailure fail(String code){return new StorageFailure("economy",code);}
    @FunctionalInterface private interface Tx<T>{T run() throws Exception;}
    private static <T>T tx(Connection c,Tx<T> work)throws Exception{c.setAutoCommit(false);try{T result=work.run();c.commit();return result;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    public CompletionStage<Void> migrate(){return db.module("economy_migrate",c->{
        byte[] bytes;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/db/economy/E001__economy.sql"))){bytes=in.readAllBytes();}
        String hash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));
        tx(c,()->{
            try(var st=c.createStatement()){st.execute("SELECT pg_advisory_xact_lock(704404009)");}
            boolean exists;try(var st=c.createStatement();var rows=st.executeQuery("SELECT to_regclass('hearth_economy.version')")){rows.next();exists=rows.getString(1)!=null;}
            if(!exists){
                try(var st=c.createStatement();var rows=st.executeQuery("SELECT to_regnamespace('hearth_economy')")){rows.next();if(rows.getString(1)!=null)throw fail("ECON_SCHEMA_MISMATCH");}
                try(var st=c.createStatement()){st.execute(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));}
                try(var insert=c.prepareStatement("INSERT INTO hearth_economy.version VALUES(1,?)")){insert.setString(1,hash);insert.executeUpdate();}
            }else{
                try(var st=c.createStatement();var versions=st.executeQuery("SELECT version,checksum FROM hearth_economy.version ORDER BY version")){if(!versions.next()||versions.getInt(1)!=1||!hash.equals(versions.getString(2)))throw fail("ECON_SCHEMA_MISMATCH");}
            }
            byte[] upgrade;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/db/economy/E002__trade_history.sql"))){upgrade=in.readAllBytes();}
            String upgradeHash=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(upgrade));
            try(var st=c.createStatement();var rows=st.executeQuery("SELECT version,checksum FROM hearth_economy.version WHERE version<>1 ORDER BY version")){
                if(rows.next()){if(rows.getInt(1)!=2||!upgradeHash.equals(rows.getString(2))||rows.next())throw fail("ECON_SCHEMA_MISMATCH");}
                else{try(var ddl=c.createStatement()){ddl.execute(new String(upgrade,java.nio.charset.StandardCharsets.UTF_8));}try(var marker=c.prepareStatement("INSERT INTO hearth_economy.version VALUES(2,?)")){marker.setString(1,upgradeHash);marker.executeUpdate();}}
            }
            for(String query:List.of("SELECT tick,revision,content_hash FROM hearth_economy.realm LIMIT 0","SELECT stock,price,revision FROM hearth_economy.market LIMIT 0","SELECT balance,payload,inventory_revision FROM hearth_economy.account LIMIT 0","SELECT due_tick,arrived FROM hearth_economy.shipment LIMIT 0","SELECT fingerprint,total FROM hearth_economy.trade LIMIT 0"))try(var st=c.createStatement()){st.executeQuery(query).close();}
            return null;
        });ready=true;return null;
    });}
    private long[] realm(Connection c,UUID realm,boolean lock)throws Exception{if(!ready)throw fail("SCHEMA_NOT_READY");try(var st=c.prepareStatement("SELECT tick,revision,wall_millis,content_hash FROM hearth_economy.realm WHERE realm_id=?"+(lock?" FOR UPDATE":""))){st.setObject(1,realm);try(var r=st.executeQuery()){if(!r.next())throw fail("ECON_REALM_MISSING");if(!contentHash.equals(r.getString(4)))throw fail("ECON_CONTENT_MISMATCH");return new long[]{r.getLong(1),r.getLong(2),r.getLong(3)};}}}
    public CompletionStage<Void> createRealm(UUID realm,long wall){return db.module("economy_create",c->tx(c,()->{if(!ready)throw fail("SCHEMA_NOT_READY");try(var st=c.prepareStatement("INSERT INTO hearth_economy.realm VALUES(?,?,0,0,?)")){st.setObject(1,realm);st.setString(2,contentHash);st.setLong(3,wall);st.executeUpdate();}try(var st=c.prepareStatement("INSERT INTO hearth_economy.market VALUES(?,?,?,?,?,0)")){for(var e:initial(content).markets().entrySet()){st.setObject(1,realm);st.setString(2,e.getKey().region());st.setString(3,e.getKey().good());st.setLong(4,e.getValue().stock());st.setLong(5,e.getValue().price());st.addBatch();}st.executeBatch();}return null;}));}
    public CompletionStage<Void> createAccount(ServerProgressAccess.Context ctx,long balance,InventoryPayload payload){return db.module("economy_account_create",c->{access(ctx);realm(c,ctx.storyRunId(),false);if(balance<0)throw fail("ECON_BALANCE");try(var st=c.prepareStatement("INSERT INTO hearth_economy.account VALUES(?,?,?,?,0)")){owner(st,ctx);st.setLong(3,balance);st.setBytes(4,payload.bytes());st.executeUpdate();}return null;});}
    private static void owner(PreparedStatement st,ServerProgressAccess.Context ctx)throws SQLException{st.setObject(1,ctx.storyRunId());st.setObject(2,ctx.playerId());}
    private Account account(Connection c,ServerProgressAccess.Context ctx,boolean lock)throws Exception{access(ctx);try(var st=c.prepareStatement("SELECT balance,payload,inventory_revision FROM hearth_economy.account WHERE realm_id=? AND player_uuid=?"+(lock?" FOR UPDATE":""))){owner(st,ctx);try(var r=st.executeQuery()){if(!r.next())throw fail("ECON_ACCOUNT_MISSING");return new Account(r.getLong(1),new Stored(InventoryPayload.parse(r.getBytes(2)),r.getLong(3)));}}}
    public CompletionStage<Account> account(ServerProgressAccess.Context ctx){return db.module("economy_account",c->account(c,ctx,false));}
    @Override public CompletionStage<Stored> createInventory(ServerProgressAccess.Context ctx,InventoryPayload initial){return CompletableFuture.failedFuture(fail("EXPLICIT_ACCOUNT_REQUIRED"));}
    @Override public CompletionStage<Stored> readInventory(ServerProgressAccess.Context ctx){return account(ctx).thenApply(Account::inventory);}
    @Override public CompletionStage<Stored> saveInventory(ServerProgressAccess.Context ctx,long revision,InventoryPayload payload){return db.module("economy_inventory",c->{access(ctx);try(var st=c.prepareStatement("UPDATE hearth_economy.account SET payload=?,inventory_revision=inventory_revision+1 WHERE realm_id=? AND player_uuid=? AND inventory_revision=?")){st.setBytes(1,payload.bytes());st.setObject(2,ctx.storyRunId());st.setObject(3,ctx.playerId());st.setLong(4,revision);if(st.executeUpdate()!=1)throw fail("CAS_CONFLICT");}return new Stored(payload,revision+1);});}
    private Market market(Connection c,UUID realm,Key key)throws Exception{try(var st=c.prepareStatement("SELECT stock,price,revision FROM hearth_economy.market WHERE realm_id=? AND region_id=? AND good_id=?")){st.setObject(1,realm);st.setString(2,key.region());st.setString(3,key.good());try(var r=st.executeQuery()){if(!r.next())throw fail("ECON_MARKET_MISSING");return new Market(r.getLong(1),r.getLong(2),r.getLong(3));}}}
    public CompletionStage<Offer> offer(ServerProgressAccess.Context ctx,Key key){return db.module("economy_offer",c->{access(ctx);return tx(c,()->{realm(c,ctx.storyRunId(),true);return new Offer(key,market(c,ctx.storyRunId(),key),account(c,ctx,false).balance());});});}
    /** 상점 한 화면의 상품은 한 작업/계정 조회로 읽습니다. 클라이언트가 지역·소유자를 정하지 않습니다. */
    public CompletionStage<List<Offer>> offers(ServerProgressAccess.Context ctx,String region,List<String> goods){
        var selected=List.copyOf(goods);if(selected.isEmpty()||selected.size()>64||new HashSet<>(selected).size()!=selected.size()||!content.regions().contains(region)||!content.goods().keySet().containsAll(selected))throw new IllegalArgumentException("ECON_SHOP_REF");
        return db.module("economy_offers",c->{access(ctx);return tx(c,()->{realm(c,ctx.storyRunId(),true);var a=account(c,ctx,false);var byGood=new HashMap<String,Market>();
            try(var st=c.prepareStatement("SELECT good_id,stock,price,revision FROM hearth_economy.market WHERE realm_id=? AND region_id=?")){st.setObject(1,ctx.storyRunId());st.setString(2,region);try(var rows=st.executeQuery()){while(rows.next())byGood.put(rows.getString(1),new Market(rows.getLong(2),rows.getLong(3),rows.getLong(4)));}}
            var result=new ArrayList<Offer>();for(String good:selected){var m=byGood.get(good);if(m==null)throw fail("ECON_MARKET_MISSING");result.add(new Offer(new Key(region,good),m,a.balance()));}return List.copyOf(result);
        });});
    }
    private static Entry entry(ResultSet r)throws SQLException{return new Entry(r.getObject(1,UUID.class),new Key(r.getString(2),r.getString(3)),r.getInt(4),r.getBoolean(5),r.getLong(6),r.getLong(7));}
    /** 계정 revision 내림차순 keyset 조회. payload·다른 플레이어 정보는 표시 DTO에 포함하지 않습니다. */
    public CompletionStage<List<Entry>> history(ServerProgressAccess.Context ctx,long before,int limit){
        if(before<1||limit<1||limit>20)throw new IllegalArgumentException("ECON_HISTORY_PAGE");
        return db.module("economy_history",c->{access(ctx);account(c,ctx,false);var result=new ArrayList<Entry>();
            try(var st=c.prepareStatement("SELECT request_id,region_id,good_id,quantity,buy,total,inventory_revision FROM hearth_economy.trade WHERE realm_id=? AND player_uuid=? AND inventory_revision<? ORDER BY inventory_revision DESC LIMIT ?")){owner(st,ctx);st.setLong(3,before);st.setInt(4,limit);try(var rows=st.executeQuery()){while(rows.next())result.add(entry(rows));}}return List.copyOf(result);
        });
    }
    /** 미확정 거래와 계정은 같은 realm 잠금 아래 비교합니다. 없는 영수증을 재실행하지 않습니다. */
    public CompletionStage<Inspection> inspect(Request request){return db.module("economy_inspect",c->{access(request.context());return tx(c,()->{
        realm(c,request.context().storyRunId(),true);Optional<Entry> found=Optional.empty();
        try(var st=c.prepareStatement("SELECT request_id,region_id,good_id,quantity,buy,total,inventory_revision,player_uuid,fingerprint FROM hearth_economy.trade WHERE realm_id=? AND request_id=?")){st.setObject(1,request.context().storyRunId());st.setObject(2,request.id());try(var rows=st.executeQuery()){if(rows.next()){if(!rows.getObject(8,UUID.class).equals(request.context().playerId())||!rows.getString(9).equals(request.fingerprint()))throw fail("ECON_REQUEST_CONFLICT");found=Optional.of(entry(rows));}}}
        return new Inspection(found,account(c,request.context(),false));
    });});}
    private Optional<Receipt> receipt(Connection c,ServerProgressAccess.Context ctx,UUID id,String fingerprint)throws Exception{try(var st=c.prepareStatement("SELECT player_uuid,fingerprint,total FROM hearth_economy.trade WHERE realm_id=? AND request_id=?")){st.setObject(1,ctx.storyRunId());st.setObject(2,id);try(var r=st.executeQuery()){if(!r.next())return Optional.empty();if(!r.getObject(1,UUID.class).equals(ctx.playerId())||fingerprint!=null&&!fingerprint.equals(r.getString(2)))throw fail("ECON_REQUEST_CONFLICT");return Optional.of(new Receipt(id,r.getLong(3),account(c,ctx,false),true));}}}
    public CompletionStage<Optional<Receipt>> receipt(ServerProgressAccess.Context ctx,UUID id){return db.module("economy_receipt",c->{access(ctx);return receipt(c,ctx,id,null);});}
    public CompletionStage<Receipt> trade(Request request,Stored before,InventoryPayload after,BooleanSupplier valid,Probe probe){return db.module("economy_trade",c->{access(request.context());var result=tx(c,()->{
        var ctx=request.context();realm(c,ctx.storyRunId(),true);var previous=receipt(c,ctx,request.id(),request.fingerprint());if(previous.isPresent())return previous.get();if(!valid.getAsBoolean())throw fail("STALE_CONTEXT");var current=account(c,ctx,true);if(current.inventory().revision()!=before.revision()||!current.inventory().payload().equals(before.payload()))throw fail("CAS_CONFLICT");var market=market(c,ctx.storyRunId(),request.key());if(market.revision()!=request.marketRevision())throw fail("ECON_QUOTE_CHANGED");if(request.buy()&&market.stock()<request.quantity())throw fail("ECON_STOCK");long total=quote(content,request.key().good(),market,request.quantity(),request.buy());long balance=request.buy()?Math.subtractExact(current.balance(),total):Math.addExact(current.balance(),total);if(balance<0)throw fail("ECON_FUNDS");long stock=request.buy()?market.stock()-request.quantity():Math.addExact(market.stock(),request.quantity());if(stock>MAX_STOCK)throw fail("ECON_STOCK");
        try(var st=c.prepareStatement("UPDATE hearth_economy.account SET balance=?,payload=?,inventory_revision=inventory_revision+1 WHERE realm_id=? AND player_uuid=? AND inventory_revision=?")){st.setLong(1,balance);st.setBytes(2,after.bytes());st.setObject(3,ctx.storyRunId());st.setObject(4,ctx.playerId());st.setLong(5,before.revision());if(st.executeUpdate()!=1)throw fail("CAS_CONFLICT");}
        try(var st=c.prepareStatement("UPDATE hearth_economy.market SET stock=?,revision=revision+1 WHERE realm_id=? AND region_id=? AND good_id=? AND revision=?")){st.setLong(1,stock);st.setObject(2,ctx.storyRunId());st.setString(3,request.key().region());st.setString(4,request.key().good());st.setLong(5,market.revision());if(st.executeUpdate()!=1)throw fail("CAS_CONFLICT");}
        try(var st=c.prepareStatement("INSERT INTO hearth_economy.trade VALUES(?,?,?,?,?,?,?,?,?,?)")){owner(st,ctx);st.setObject(3,request.id());st.setString(4,request.fingerprint());st.setString(5,request.key().region());st.setString(6,request.key().good());st.setInt(7,request.quantity());st.setBoolean(8,request.buy());st.setLong(9,total);st.setLong(10,before.revision()+1);st.executeUpdate();}if(probe==Probe.ROLLBACK)throw new SQLException("Injected rollback","23514");if(!valid.getAsBoolean())throw fail("STALE_CONTEXT");return new Receipt(request.id(),total,new Account(balance,new Stored(after,before.revision()+1)),false);
        });if(probe==Probe.COMMIT_UNKNOWN)throw fail("COMMIT_UNKNOWN");return result;});}
    private State snapshot(Connection c,UUID realm,long tick)throws Exception{var markets=new TreeMap<Key,Market>();try(var st=c.prepareStatement("SELECT region_id,good_id,stock,price,revision FROM hearth_economy.market WHERE realm_id=?")){st.setObject(1,realm);try(var r=st.executeQuery()){while(r.next())markets.put(new Key(r.getString(1),r.getString(2)),new Market(r.getLong(3),r.getLong(4),r.getLong(5)));}}
        var shipments=new ArrayList<Shipment>();try(var st=c.prepareStatement("SELECT request_id,route_id,from_region,to_region,good_id,quantity,due_tick FROM hearth_economy.shipment WHERE realm_id=? AND NOT arrived ORDER BY due_tick,request_id")){st.setObject(1,realm);try(var r=st.executeQuery()){while(r.next())shipments.add(new Shipment(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getLong(6),r.getLong(7)));}}
        var events=new ArrayList<Active>();try(var st=c.prepareStatement("SELECT request_id,event_id,start_tick,end_tick FROM hearth_economy.event WHERE realm_id=? AND NOT expired ORDER BY request_id")){st.setObject(1,realm);try(var r=st.executeQuery()){while(r.next())events.add(new Active(r.getObject(1,UUID.class),r.getString(2),r.getLong(3),r.getLong(4)));}}return new State(tick,markets,shipments,events);}
    public CompletionStage<State> snapshot(UUID realm){return db.module("economy_snapshot",c->tx(c,()->snapshot(c,realm,realm(c,realm,true)[0])));}
    private void advanceStored(Connection c,UUID realm,long[] clock,long wall)throws Exception{var before=snapshot(c,realm,clock[0]);var step=advance(realm,content,before);
        try(var st=c.prepareStatement("UPDATE hearth_economy.market SET stock=?,price=?,revision=? WHERE realm_id=? AND region_id=? AND good_id=?")){for(var e:step.state().markets().entrySet()){var old=before.markets().get(e.getKey());if(old.stock()==e.getValue().stock()&&old.price()==e.getValue().price())continue;st.setLong(1,e.getValue().stock());st.setLong(2,e.getValue().price());st.setLong(3,e.getValue().revision());st.setObject(4,realm);st.setString(5,e.getKey().region());st.setString(6,e.getKey().good());st.addBatch();}st.executeBatch();}
        try(var st=c.prepareStatement("INSERT INTO hearth_economy.shipment VALUES(?,?,?,?,?,?,?,?,false)")){for(var x:step.departed()){st.setObject(1,realm);st.setObject(2,x.request());st.setString(3,x.route());st.setString(4,x.from());st.setString(5,x.to());st.setString(6,x.good());st.setLong(7,x.quantity());st.setLong(8,x.due());st.addBatch();}st.executeBatch();}
        for(var pair:List.of(Map.entry("shipment",step.arrived()),Map.entry("event",step.expired())))try(var st=c.prepareStatement("UPDATE hearth_economy."+pair.getKey()+" SET "+(pair.getKey().equals("shipment")?"arrived":"expired")+"=true WHERE realm_id=? AND request_id=?")){for(UUID id:pair.getValue()){st.setObject(1,realm);st.setObject(2,id);st.addBatch();}st.executeBatch();}
        try(var st=c.prepareStatement("UPDATE hearth_economy.realm SET tick=tick+1,revision=revision+1,wall_millis=? WHERE realm_id=? AND tick=?")){st.setLong(1,wall);st.setObject(2,realm);st.setLong(3,clock[0]);if(st.executeUpdate()!=1)throw fail("CAS_CONFLICT");}}
    public CompletionStage<Boolean> tick(UUID realm,long expected,long wall){return db.module("economy_tick",c->tx(c,()->{var clock=realm(c,realm,true);if(clock[0]!=expected)return false;if(wall<clock[2])throw fail("ECON_CLOCK_REVERSED");advanceStored(c,realm,clock,wall);return true;}));}
    /** 재시작 처리도 같은 realm 잠금과 트랜잭션 안에서 수행합니다. 초과 경과분은 개발 설정에 따라 버립니다. */
    public CompletionStage<Integer> resumeClock(UUID realm,long wall){return db.module("economy_resume",c->tx(c,()->{var clock=realm(c,realm,true);int count=offlineTicks(content,clock[2],wall);for(int i=0;i<count;i++){advanceStored(c,realm,clock,wall);clock[0]++;}try(var st=c.prepareStatement("UPDATE hearth_economy.realm SET wall_millis=? WHERE realm_id=?")){st.setLong(1,wall);st.setObject(2,realm);st.executeUpdate();}return count;}));}
    public static int offlineTicks(EconomyContent c,long previous,long now){if(now<previous)throw fail("ECON_CLOCK_REVERSED");return c.offline().equals("PAUSE")?0:(int)Math.min(c.catchup(),(now-previous)/c.tickMillis());}
    public CompletionStage<Void> event(UUID realm,UUID request,String event){return db.module("economy_event",c->tx(c,()->{var clock=realm(c,realm,true);var def=content.events().get(event);if(def==null)throw fail("ECON_EVENT_MISSING");try(var st=c.prepareStatement("SELECT event_id FROM hearth_economy.event WHERE realm_id=? AND request_id=?")){st.setObject(1,realm);st.setObject(2,request);try(var r=st.executeQuery()){if(r.next()){if(!r.getString(1).equals(event))throw fail("ECON_REQUEST_CONFLICT");return null;}}}try(var st=c.prepareStatement("SELECT count(*) FROM hearth_economy.event WHERE realm_id=? AND NOT expired")){st.setObject(1,realm);try(var r=st.executeQuery()){r.next();if(r.getInt(1)>=128)throw fail("QUEUE_FULL");}}try(var st=c.prepareStatement("INSERT INTO hearth_economy.event VALUES(?,?,?,?,?,false)")){st.setObject(1,realm);st.setObject(2,request);st.setString(3,event);st.setLong(4,clock[0]+1);st.setLong(5,clock[0]+1+def.duration());st.executeUpdate();}return null;}));}
    public ProgressStore progressAdapter(){return new ProgressStore(){public CompletionStage<Void> migrate(){return EconomyStore.this.migrate();}public CompletionStage<Void> createRun(UUID id,String v){return CompletableFuture.failedFuture(fail("EXPLICIT_REALM_REQUIRED"));}public CompletionStage<Void> createPlayer(ServerProgressAccess.Context c,String v){return CompletableFuture.failedFuture(fail("EXPLICIT_ACCOUNT_REQUIRED"));}public CompletionStage<State> readShared(ServerProgressAccess.Context c){access(c);return db.module("economy_progress",sql->{var r=realm(sql,c.storyRunId(),false);return new State("경제",r[1]);});}public CompletionStage<State> readPersonal(ServerProgressAccess.Context c){return account(c).thenApply(a->new State("경제",a.inventory().revision()));}public CompletionStage<State> saveShared(ServerProgressAccess.Context c,long r,String v){return CompletableFuture.failedFuture(fail("READ_ONLY"));}public CompletionStage<State> savePersonal(ServerProgressAccess.Context c,long r,String v){return CompletableFuture.failedFuture(fail("READ_ONLY"));}public CompletionStage<Void> closeAsync(){return CompletableFuture.completedFuture(null);}};}
}
